import{$ as e,H as t,_t as n,at as r,it as i,nt as a,rt as o,xt as s}from"./chunks/framework.B6hMYkVh.js";var c=JSON.parse(`{"title":"FAQs for self-hosted SysReptor","description":"","frontmatter":{},"headers":[],"relativePath":"faq/self-hosted.md","filePath":"faq/self-hosted.md","lastUpdated":1789542840000}`),l={name:`faq/self-hosted.md`},u={class:`info custom-block`},d={class:`custom-block-title`};function f(t,c,l,f,p,m){let h=s(`FaqExpandAll`),g=s(`DocBadge`);return n(),a(`div`,null,[c[1]||=o(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /faq/self-hosted.md for this page in Markdown format</div><h1 id="faqs-for-self-hosted-sysreptor" tabindex="-1">FAQs for self-hosted SysReptor <a class="header-anchor" href="#faqs-for-self-hosted-sysreptor" aria-label="Permalink to “FAQs for self-hosted SysReptor”">​</a></h1><p>These FAQs are for operators who install SysReptor with Docker on their own server.</p><p>Students writing HTB or OffSec exam reports on <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a> should use the <a href="/faq/exam-reports">exam report FAQs</a>. SysReptor Cloud is covered in the <a href="/faq/cloud">cloud FAQs</a>.</p>`,4),r(h),c[2]||=o(`<div class="faq-item"><details class="details custom-block"><summary>Can I install SysReptor on macOS or Linux distributions like Kali, Fedora, RHEL?</summary><p>Even though we officially support <strong>Ubuntu</strong> only, installation is technically possible on most UNIX-based target systems including Kali, Fedora, macOS or RHEL.</p><p>The installation of dependencies (like docker, sed, curl, openssl, uuid-runtime, coreutils, cron; some of them are optional) might vary from system to system. Follow the steps for <a href="/setup/installation#manual-installation">manual installations</a> and adapt the commands according to your system.</p><p>If all dependencies are installed and are ready to use, <a href="/setup/installation#easy-script-installation">easy script installation</a> might also work.</p></details></div><div class="faq-item" id="windows"><details class="details custom-block"><summary>Can I install SysReptor on Windows?</summary><p>The easiest approach on Windows is to install SysReptor in <a href="https://learn.microsoft.com/en-us/windows/wsl/install" target="_blank" rel="noreferrer">Windows Subsystem for Linux 2</a> (WSL 2) with an Ubuntu distribution.</p><p>Make sure to install Docker Desktop with WSL 2 and to enable integration of Docker with WSL (in Docker Desktop go to <strong>Settings → Resources → WSL Integration → Enable integration with my default WSL distro</strong>).</p></details></div><div class="faq-item"><details class="details custom-block"><summary>What are the SysReptor system requirements for a self-hosted install?</summary><p>For a self-hosted SysReptor server, the requirements are Ubuntu and 8 GB RAM. The application runs in Docker. Details and client browser requirements are in <a href="/setup/installation">Installation</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>What is the SysReptor default password?</summary><p>SysReptor has <strong>no fixed default password</strong>.</p><ul><li>The <a href="/setup/installation">install script</a> creates a superuser named <code>reptor</code> and prints a <strong>random password once</strong>. Store it when it is shown; it is not saved in the docs or in a default config file.</li><li>A <a href="/setup/installation">manual install</a> uses <code>createsuperuser</code>, so you choose the username and password yourself.</li></ul><p>If you lost the password, reset it from the CLI. From <code>sysreptor/deploy</code> run:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changepassword</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;username&gt;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Use the username from install (<code>reptor</code> if you used the install script). The command prompts twice for a new password, then updates that user. You can log in with the new password immediately.</p><p>If no user was created yet, create a superuser from the same directory:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> createsuperuser</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;username&gt;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The command prompts twice for a password. You can log in with that username and password immediately.</p></details></div><div class="faq-item" id="uninstall"><details class="details custom-block"><summary>How do I cleanly uninstall SysReptor and delete all data?</summary><p>To uninstall a self-hosted SysReptor and delete all data (database and uploaded files), remove the Docker containers, named volumes, and the install directory.</p><p>From the <code>sysreptor/deploy</code> directory, stop the stack, then delete containers and volumes:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor/deploy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor-db</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor-app-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor-db-data</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>If you used Caddy from the bundled compose file, also remove <code>sysreptor-caddy-data</code>. Then delete the <code>sysreptor</code> directory on disk.</p><p>This cannot be undone. Create a <a href="/setup/backups">backup</a> first if you might need the data.</p><p>To stop SysReptor <strong>without</strong> deleting data, see <a href="#stop-without-deleting">How do I stop SysReptor without deleting data?</a>.</p></details></div><div class="faq-item" id="stop-without-deleting"><details class="details custom-block"><summary>How do I stop SysReptor without deleting data?</summary><p>To stop a self-hosted SysReptor without deleting volumes or files, go to <code>sysreptor/deploy</code> and run:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Your database and uploaded files stay in the Docker volumes.<br> To start again: <code>docker compose up -d</code>.</p></details></div><div class="faq-item" id="verify-integrity"><details class="details custom-block"><summary>How do I verify the integrity of a SysReptor installation?</summary><p>Verify Docker images or the release archive (<code>setup.tar.gz</code>) with <a href="https://docs.sigstore.dev/cosign/system_config/installation/" target="_blank" rel="noreferrer">cosign</a>. The SysReptor public key is <a href="https://docs.sysreptor.com/cosign.pub" target="_blank" rel="noreferrer">https://docs.sysreptor.com/cosign.pub</a>.</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SYSREPTOR_VERSION</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor/deploy/.env</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SYSREPTOR_VERSION=&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cut</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;=&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f2-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># SYSREPTOR_VERSION=$(docker exec -it sysreptor-app bash -c &#39;echo &quot;$VERSION&quot;&#39;)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Verify docker images</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docs.sysreptor.com/cosign.pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;syslifters/sysreptor:\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SYSREPTOR_VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docs.sysreptor.com/cosign.pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;syslifters/sysreptor-languagetool:\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SYSREPTOR_VERSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Pro only</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Verify setup.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor.tar.gz.sigstore.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Syslifters/sysreptor/releases/download/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\${SYSREPTOR_VERSION}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/setup.tar.gz.sigstore.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-blob</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docs.sysreptor.com/cosign.pub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor.tar.gz.sigstore.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><code>verify-blob</code> needs the local <code>sysreptor.tar.gz</code> you downloaded from GitHub Releases. The same steps are in <a href="/setup/installation">Installation</a> and <a href="/setup/updates">Updates</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I update a self-hosted SysReptor?</summary><p>Update a self-hosted SysReptor with the bundled script (recommended):</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysreptor/update.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Professional installations can add <code>--backup</code> to create a backup before the update. Full steps, manual updates, and image verification are in <a href="/setup/updates">Updates</a>. Create a <a href="/setup/backups">backup</a> before updating.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I back up and restore a self-hosted SysReptor instance?</summary><p>On a self-hosted SysReptor you can back up via CLI, and (with Professional, a superuser, and <a href="/setup/configuration#backup-key"><code>BACKUP_KEY</code></a>) via the web UI or API. The archive contains all data from your installation, including users, projects, templates, designs, assets, settings, the database export and uploaded files.</p><p>CLI example from <code>sysreptor/deploy</code>:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup.zip</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Restore deletes existing data in the database and file storage. Use the same SysReptor version. Full commands: <a href="/setup/backups#restore-backups">Backups</a>.</p></details></div><div class="faq-item"><details class="details custom-block"><summary>How do I add a SysReptor Professional license to a self-hosted install?</summary><p>Add your license key to <code>deploy/app.env</code> as <code>LICENSE=&#39;your_license_key&#39;</code>, include the LanguageTool compose file if needed, and run <code>docker compose up -d</code> from <code>deploy</code>. You do not need to reinstall. No data is lost during the transition from Community to Professional or vice versa.</p><p>See <a href="/setup/upgrade-to-professional">Upgrade to Professional</a> for more details.</p></details></div>`,10),e(`div`,u,[e(`p`,d,[r(g,{icon:`mdi:help-circle`,class:`lg middle`,label:`Further questions?`})]),c[0]||=e(`p`,null,[i(`Need help or have questions? Get support and `),e(`a`,{href:`https://github.com/Syslifters/sysreptor/discussions/`,target:`_blank`,rel:`noreferrer`},`connect with us and the SysReptor community`),i(`.`)],-1)])])}var p=t(l,[[`render`,f]]);export{c as __pageData,p as default};